import pandas as pd

def clean(df):
    df = df.copy()
    df['Category'] = df['Category'].str.strip()
    df['Category'] = df['Category'].replace({'office supplies': 'Office Supplies'})
    df = df.drop_duplicates()
    return df

def answer(df):
    df = clean(df)
    return df.groupby('Category').size().to_dict()
